// The owner's numbers page at /owner/numbers: income and API cost side by side, private to one
// person behind HTTP Basic authentication, rendered here with no JavaScript. The approved
// design is design/canvas/project/Owner-Numbers.dc.html (generated by design/scratch/paid/paid.py):
// type and rules only, no boxes, radius 0. It also writes the daily snapshot the "By month"
// table reads, from the Cron Trigger in wrangler.jsonc.
//
// HTTP Basic: https://www.rfc-editor.org/rfc/rfc7617

import { costKey, parseMonth, type MonthCost } from "./cost";
import { base64Decode, decodeUtf8, sha256Hex, utf8 } from "./encoding";
import { countingFields, firstSubscriberAt, liveCounts, monthEndSnapshots, saveSnapshot, type Counts } from "./store";
import { FIELDS } from "./subscriptions";

export interface OwnerEnv {
  DB?: D1Database;
  CONTENT: R2Bucket;
  OWNER_PASSWORD?: string;
  LIST_PRICE_USD?: string;
  GOOGLE_FEE_PERCENT?: string;
  COUNT_TRIALS?: string;
}

// Google's service fee on auto-renewing subscriptions: "10% + 5% billing fee" in every row of
// the US fee table, https://support.google.com/googleplay/android-developer/answer/112622
// (quoted in .private/research/play-store.md, section 4).
const DEFAULT_FEE_PERCENT = 15;
// How many months the "By month" table goes back at most.
const MONTHS_SHOWN = 24;

const LABELS: Record<string, string> = {
  physics: "Physics",
  space: "Space",
  math: "Math",
  cs: "Computer science",
  biology: "Biology",
  neuroscience: "Neuroscience",
  medicine: "Medicine",
  chemistry: "Chemistry",
  earth: "Earth",
  engineering: "Engineering",
  social: "Social science",
};
const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

type Read = (env: OwnerEnv, key: string) => Promise<string | "missing" | "unreachable">;

// A month's cost, or why it is not known.
type CostReading = MonthCost | "unreadable";

export interface MonthRow {
  month: string;
  paying: number | null;
  income: number | null;
  cost: CostReading;
}

export interface Numbers {
  month: string;
  paying: number;
  trials: number;
  // Null when LIST_PRICE_USD is not set.
  income: number | null;
  cost: CostReading;
  fields: { field: string; picked: number; pages: number; cost: number; making: boolean }[];
  months: MonthRow[];
}

export function monthOf(ms: number): string {
  return new Date(ms).toISOString().slice(0, 7);
}

function previousMonth(month: string): string {
  const [y, m] = month.split("-").map(Number);
  return m === 1 ? `${y - 1}-12` : `${y}-${String(m - 1).padStart(2, "0")}`;
}

function price(env: OwnerEnv): number | null {
  const text = (env.LIST_PRICE_USD ?? "").trim();
  if (!/^\d+(\.\d+)?$/.test(text)) return null;
  const value = Number(text);
  return value > 0 ? value : null;
}

function feePercent(env: OwnerEnv): number {
  const text = (env.GOOGLE_FEE_PERCENT ?? "").trim();
  const value = Number(text);
  return text !== "" && Number.isFinite(value) && value >= 0 && value <= 100 ? value : DEFAULT_FEE_PERCENT;
}

// Income after Google's cut for a subscriber count: the count times the listed monthly price
// times (1 minus Google's fee). An estimate: real payouts come from Google's reports.
export function income(paying: number, env: OwnerEnv): number | null {
  const p = price(env);
  return p === null ? null : paying * p * (1 - feePercent(env) / 100);
}

export function createOwner(deps: { now: () => number; read: Read }) {
  async function monthCost(env: OwnerEnv, month: string): Promise<CostReading> {
    const text = await deps.read(env, costKey(month));
    // A month with no cost file had no API runs.
    if (text === "missing") return { spend: 0, runs: 0, pages: {}, costByField: {} };
    if (text === "unreachable") return "unreadable";
    return parseMonth(text) ?? "unreadable";
  }

  async function gather(env: OwnerEnv, db: D1Database): Promise<Numbers> {
    const now = deps.now();
    const month = monthOf(now);
    const [live, active, snapshots, first] = await Promise.all([
      liveCounts(db, now),
      countingFields(db, env.COUNT_TRIALS !== "false", now),
      monthEndSnapshots(db, MONTHS_SHOWN),
      firstSubscriberAt(db),
    ]);
    const making = new Set(active.flat());

    // From this month back to the first month anything was recorded.
    let earliest = month;
    for (const s of snapshots) if (s.day.slice(0, 7) < earliest) earliest = s.day.slice(0, 7);
    if (first !== null && monthOf(first) < earliest) earliest = monthOf(first);
    const months: string[] = [];
    for (let m = month; m >= earliest && months.length < MONTHS_SHOWN; m = previousMonth(m)) months.push(m);

    const costs = await Promise.all(months.map((m) => monthCost(env, m)));
    const byMonth = new Map(snapshots.map((s) => [s.day.slice(0, 7), s]));
    const current = costs[0];
    const rows: MonthRow[] = months.map((m, i) => {
      // This month uses live counts; a past month its last snapshot.
      const paying = i === 0 ? live.paying : (byMonth.get(m)?.paying ?? null);
      return { month: m, paying, income: paying === null ? null : income(paying, env), cost: costs[i] };
    });

    return {
      month,
      paying: live.paying,
      trials: live.trials,
      income: income(live.paying, env),
      cost: current,
      fields: FIELDS.map((field) => ({
        field,
        picked: live.fields[field] ?? 0,
        pages: current === "unreadable" ? 0 : (current.pages[field] ?? 0),
        cost: current === "unreadable" ? 0 : (current.costByField[field] ?? 0),
        making: making.has(field),
      })),
      months: rows,
    };
  }

  // True when the request carries HTTP Basic credentials whose password is OWNER_PASSWORD.
  // Any username. Both sides are hashed first so the comparison is constant time over equal
  // lengths.
  async function authorized(request: Request, password: string): Promise<boolean> {
    const match = /^Basic ([A-Za-z0-9+/=]+)$/i.exec((request.headers.get("authorization") ?? "").trim());
    if (!match) return false;
    const bytes = base64Decode(match[1]);
    const text = bytes && decodeUtf8(bytes);
    if (typeof text !== "string") return false;
    const colon = text.indexOf(":");
    if (colon < 0) return false;
    const given = utf8(await sha256Hex(text.slice(colon + 1)));
    const expected = utf8(await sha256Hex(password));
    return crypto.subtle.timingSafeEqual(given, expected);
  }

  return {
    async fetch(request: Request, env: OwnerEnv): Promise<Response> {
      const path = new URL(request.url).pathname;
      // Only in the paid worker, and never open: no database or no password is a 404.
      if (path !== "/owner/numbers" || !env.DB || !env.OWNER_PASSWORD) {
        await request.body?.cancel();
        return plain(404, "Not found\n");
      }
      if (request.method !== "GET" && request.method !== "HEAD") {
        await request.body?.cancel();
        return plain(405, "Method not allowed\n", { allow: "GET, HEAD" });
      }
      if (!(await authorized(request, env.OWNER_PASSWORD))) {
        return plain(401, "Password required\n", { "www-authenticate": 'Basic realm="Paperboy numbers", charset="UTF-8"' });
      }
      const html = renderNumbers(await gather(env, env.DB));
      const headers = new Headers({
        "content-type": "text/html; charset=utf-8",
        "content-security-policy": await pagePolicy(),
        ...PRIVATE_HEADERS,
      });
      return new Response(request.method === "HEAD" ? null : html, { headers });
    },

    // Writes today's (UTC) counts. A second run on the same day replaces the first.
    async snapshot(env: OwnerEnv, at: number): Promise<void> {
      if (!env.DB) return;
      const counts: Counts = await liveCounts(env.DB, at);
      await saveSnapshot(env.DB, new Date(at).toISOString().slice(0, 10), counts, deps.now());
    },
  };
}

const PRIVATE_HEADERS = {
  "cache-control": "no-store",
  "x-robots-tag": "noindex",
  "referrer-policy": "no-referrer",
  "x-content-type-options": "nosniff",
};

function plain(status: number, text: string, extra: Record<string, string> = {}): Response {
  return new Response(text, { status, headers: { "content-type": "text/plain; charset=utf-8", ...PRIVATE_HEADERS, ...extra } });
}

// ------------------------------------------------------------------ the page

// Tokens from design/SYSTEM.md, as the board uses them.
const INK = "#16130F";
const MUTED = "#5A554B";
const STOCK = "#E9E6DE";
const DISP = "'Noto Serif Display', Didot, 'Bodoni MT', Georgia, serif";
const TEXT = "'Source Serif 4', Georgia, 'Times New Roman', serif";
const MONO = "'Martian Mono', 'DejaVu Sans Mono', Menlo, monospace";

// The board's PAGE_CSS and its inline styles, as classes, so the page needs no inline style
// attributes and the policy can allow this one style element by its hash.
export const PAGE_STYLE = `body{margin:0;background-color:${STOCK};color:${INK};font-family:${TEXT}}
:root{--on-pad:40px 56px 96px;--on-h1:66px;--on-h1-lh:0.95;--on-num:48px;--on-body:19px;--on-note:16px;--on-lab:11px;--on-figs:repeat(4,minmax(0,1fr));--on-gap:56px}
@media (max-width:1159px){:root{--on-pad:24px 20px 56px;--on-h1:44px;--on-h1-lh:0.98;--on-num:44px;--on-body:17px;--on-note:15px;--on-lab:10.5px;--on-gap:40px}}
@media (max-width:759px){:root{--on-figs:repeat(2,minmax(0,1fr))}}
@media (max-width:419px){:root{--on-figs:repeat(1,minmax(0,1fr))}}
.wrap{max-width:1200px;margin:0 auto;box-sizing:border-box;padding:var(--on-pad);display:flex;flex-direction:column}
.r3{height:3px;background-color:${INK}}.r1{height:0.75px;background-color:${INK};margin-top:2px}
h1{margin:14px 0 0;font-family:${DISP};font-size:var(--on-h1);line-height:var(--on-h1-lh);font-weight:800;font-stretch:62.5%;letter-spacing:-0.005em}
section{margin-top:var(--on-gap);display:flex;flex-direction:column}
.lab{font-family:${MONO};font-stretch:75%;font-size:var(--on-lab);letter-spacing:0.06em;line-height:1.3;text-transform:uppercase}
.headrow{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-top:12px}
.headrow .left{font-weight:600;color:${INK}}.headrow .right{font-weight:500;color:${MUTED};text-align:right}
.figs{display:grid;grid-template-columns:var(--on-figs);column-gap:24px;row-gap:28px;margin-top:14px}
.fig{display:flex;flex-direction:column;border-top:0.75px solid ${INK};padding-top:10px;min-width:0}
.fig .lab{font-weight:500;color:${MUTED}}
.num{margin-top:8px;font-family:${DISP};font-size:var(--on-num);font-weight:800;font-stretch:62.5%;line-height:1;letter-spacing:-0.005em;font-variant-numeric:lining-nums}
.note{font-family:${TEXT};font-size:var(--on-note);line-height:1.4;font-style:italic;margin:8px 0 0}
.note.muted{color:${MUTED}}
.trials{margin:24px 0 0;padding-top:11px;border-top:0.75px solid ${INK};font-size:var(--on-body);line-height:1.5}
.scroll{overflow-x:auto;margin-top:14px}
table{width:100%;border-collapse:collapse}
table.fields{min-width:760px}table.months{min-width:700px}
th,td{vertical-align:baseline;padding:9px 20px 10px 0;border-bottom:0.75px solid ${INK};white-space:nowrap;text-align:left;font-weight:400}
thead th{vertical-align:bottom;padding:0 20px 8px 0;font-weight:500;color:${MUTED};white-space:normal}
th:last-child,td:last-child{padding-right:0}
.r{text-align:right}
.cell{font-family:${TEXT};font-size:var(--on-body);line-height:1.3;font-variant-numeric:lining-nums tabular-nums}
td.status{font-weight:600}
tr.off .cell,tr.off td.status{color:${MUTED}}tr.off td.status{font-weight:500}
.foot-rule{margin-top:var(--on-gap);width:64px;height:0.75px;background-color:${INK}}
.foot{margin:10px 0 0;max-width:760px;text-wrap:pretty}`;

const FONTS = [
  "NotoSerifDisplay-Roman-latin.woff2",
  "SourceSerif4-Roman-latin.woff2",
  "SourceSerif4-Italic-latin.woff2",
  "MartianMono-Roman-latin.woff2",
];

// Same-origin fonts and the kit's font stylesheet, this page's one style element, and nothing
// else: no scripts, images, frames, forms, or connections.
let policy: string | null = null;
async function pagePolicy(): Promise<string> {
  if (policy) return policy;
  const digest = await crypto.subtle.digest("SHA-256", utf8(PAGE_STYLE));
  const hash = btoa(String.fromCharCode(...new Uint8Array(digest)));
  policy = [
    "default-src 'none'",
    `style-src 'self' 'sha256-${hash}'`,
    "font-src 'self'",
    "base-uri 'none'",
    "form-action 'none'",
    "frame-ancestors 'none'",
  ].join("; ");
  return policy;
}

export function monthName(month: string): string {
  const [y, m] = month.split("-").map(Number);
  return `${MONTH_NAMES[m - 1]} ${y}`;
}

export function money(value: number): string {
  const cents = Math.round(Math.abs(value) * 100);
  if (cents === 0) return "$0";
  const text = (cents / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return `${value < 0 ? "-" : ""}$${text}`;
}

const NOT_SET = "not set";
const UNREADABLE = "cannot be read";
const NOT_RECORDED = "not recorded";

function costText(cost: CostReading): string {
  return cost === "unreadable" ? UNREADABLE : money(cost.spend);
}

function leftOver(incomeValue: number | null, cost: CostReading): number | null | "unreadable" {
  if (cost === "unreadable") return "unreadable";
  if (incomeValue === null) return null;
  return incomeValue - cost.spend;
}

function leftText(value: number | null | "unreadable", unset = NOT_SET): string {
  return value === "unreadable" ? UNREADABLE : value === null ? unset : money(value);
}

function escape(text: string): string {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function figure(label: string, value: string, under = ""): string {
  return `<div class="fig"><div class="lab">${escape(label)}</div><div class="num">${escape(value)}</div>${under}</div>`;
}

function headrow(left: string, right: string): string {
  return `<div class="headrow"><div class="lab left">${escape(left)}</div><div class="lab right">${escape(right)}</div></div>`;
}

const RULE2 = '<div class="r3"></div><div class="r1"></div>';

export function renderNumbers(n: Numbers): string {
  const left = leftOver(n.income, n.cost);
  let sentence = "";
  if (typeof left === "number") {
    sentence = left >= 0 ? "The app paid for itself this month." : `The app cost you ${money(-left)} this month.`;
  }
  const incomeNote = n.income === null ? "" : `<p class="note muted">Estimate from today's subscriber count.</p>`;
  const figs =
    figure("Subscribers", String(n.paying)) +
    figure("Income after Google's cut", n.income === null ? NOT_SET : money(n.income), incomeNote) +
    figure("API cost", costText(n.cost)) +
    figure("Left over", leftText(left), sentence ? `<p class="note">${escape(sentence)}</p>` : "");

  const fieldRows = n.fields
    .map(
      (f) =>
        `<tr${f.making ? "" : ' class="off"'}><th scope="row" class="cell">${escape(LABELS[f.field])}</th>` +
        `<td class="cell r">${f.picked}</td><td class="cell r">${f.pages}</td><td class="cell r">${escape(n.cost === "unreadable" ? UNREADABLE : money(f.cost))}</td>` +
        `<td class="lab status">${f.making ? "Making pages" : "No subscribers, no pages"}</td></tr>`,
    )
    .join("");
  const monthRows = n.months
    .map((m) => {
      const recorded = m.paying !== null;
      const inc = !recorded ? NOT_RECORDED : m.income === null ? NOT_SET : money(m.income);
      const lo = !recorded ? (m.cost === "unreadable" ? UNREADABLE : NOT_RECORDED) : leftText(leftOver(m.income, m.cost));
      return (
        `<tr><th scope="row" class="cell">${escape(monthName(m.month))}</th>` +
        `<td class="cell r">${recorded ? m.paying : NOT_RECORDED}</td><td class="cell r">${escape(inc)}</td>` +
        `<td class="cell r">${escape(costText(m.cost))}</td><td class="cell r">${escape(lo)}</td></tr>`
      );
    })
    .join("");
  const th = (text: string, right = false) => `<th scope="col" class="lab${right ? " r" : ""}">${escape(text)}</th>`;

  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="color-scheme" content="light">
<meta name="robots" content="noindex">
<title>Paperboy numbers</title>
${FONTS.map((f) => `<link rel="preload" href="/kit/v2/fonts/${f}" as="font" type="font/woff2" crossorigin>`).join("\n")}
<link rel="stylesheet" href="/kit/v2/fonts/fonts.css">
<style>${PAGE_STYLE}</style>
</head>
<body>
<div class="wrap">
${RULE2}
<h1>Paperboy numbers</h1>
<section>${RULE2}${headrow("This month", monthName(n.month))}
<div class="figs">${figs}</div>
<p class="trials">Trials not yet paying: ${n.trials}</p>
</section>
<section>${RULE2}${headrow("By field", monthName(n.month))}
<div class="scroll"><table class="fields"><thead><tr>${th("Field")}${th("Subscribers who picked it", true)}${th("Pages made this month", true)}${th("API cost this month", true)}${th("Status")}</tr></thead>
<tbody>${fieldRows}</tbody></table></div>
<p class="note muted">A run's cost is split evenly across the papers it worked on, so a field's cost is an estimate.</p>
</section>
<section>${RULE2}${headrow("By month", "Newest first")}
<div class="scroll"><table class="months"><thead><tr>${th("Month")}${th("Subscribers at month end", true)}${th("Income after Google's cut", true)}${th("API cost", true)}${th("Left over", true)}</tr></thead>
<tbody>${monthRows}</tbody></table></div>
</section>
<div class="foot-rule"></div>
<p class="note foot">Income is counted from active subscriptions at the listed price minus Google's fee. API cost comes from each run's own record.</p>
</div>
</body>
</html>
`;
}
